sys_script_include.script:
var CreateSamActiveUpgradeTasks = Class.create();
CreateSamActiveUpgradeTasks.prototype = {
    initialize: function() {},

    createTasks: function() {
        var createdTasks = [];
        var processedKPIs = [];

        var propertyName = 'sam.active.upgrade.kpi';
        var kpiData = gs.getProperty(propertyName);

        if (!kpiData) {
            gs.error('System property "' + propertyName + '" is empty or not set.');
            return {
                createdTasks: createdTasks,
                processedKPIs: processedKPIs
            };
        }

        processedKPIs.push(propertyName);
        gs.info('Processing System Property: ' + propertyName);

        try {
            var kpis = JSON.parse(kpiData);
            for (var i = 0; i < kpis.length; i++) {
                var kpi = kpis[i];

                // Validate required fields
                if (!kpi.id || !kpi.description || !kpi.recommendation) {
                    gs.error('Missing required fields for KPI: ' + JSON.stringify(kpi));
                    continue;
                }

                // Check if task already exists
                var existingTask = new GlideRecord('samp_sp_vb_task');
                existingTask.addQuery('name', kpi.id);
                existingTask.addQuery('description', kpi.description);
                existingTask.addEncodedQuery('stateNOT IN2,-5,3,7'); // Exclude closed or inactive states
                existingTask.query();

                if (existingTask.next()) {
                    gs.info('Task already exists for KPI: ' + kpi.id);
                    continue;
                }

                // Create a new task using recommendation as instructions
                var taskGr = new GlideRecord('samp_sp_vb_task');
                taskGr.initialize();
                taskGr.setValue('name', kpi.id);
                taskGr.setValue('short_description', 'Active or Upgrade Plugin Task');
                taskGr.setValue('description', kpi.description);
                taskGr.setValue('instructions', kpi.recommendation);
                taskGr.setValue('state', 'open');

                var taskId = taskGr.insert();
                if (taskId) {
                    gs.info('Created task for KPI: ' + kpi.id + ' (Task ID: ' + taskId + ')');
                    createdTasks.push(kpi.id);
                    gs.eventQueue('sam.implementation.value.builder.task', taskGr, taskGr.sys_id);
                }
            }
        } catch (e) {
            gs.error('Error processing system property "' + propertyName + '": ' + e.message);
        }

        return {
            createdTasks: createdTasks,
            processedKPIs: processedKPIs
        };
    },

    type: 'CreateSamActiveUpgradeTasks'
};
